using System;
using System.Drawing;
using System.Windows.Forms;
namespace VinsPDF {
internal sealed partial class EditorPalette {
 ComboBox listMode;Color? markColor;readonly Button[] alignButtons=new Button[4];readonly ToolTip tips=new ToolTip();
 void AlignmentRow(Control parent,int y){for(int n=0;n<4;n++){int a=n;var b=Mini(parent,"",5+n*51,y,46,delegate{textAlign.SelectedIndex=a;});b.Paint+=delegate(object sender,PaintEventArgs e){using(var pen=new Pen(Color.Gainsboro)){for(int i=0;i<4;i++){int w=a==3||i%2==0?24:16;int x=a==0?10:a==1?(46-w)/2:36-w;e.Graphics.DrawLine(pen,x,7+i*4,x+w,7+i*4);}}};tips.SetToolTip(b,new[]{"Align left","Align centre","Align right","Justify"}[n]);alignButtons[n]=b;}textAlign.SelectedIndexChanged+=delegate{for(int i=0;i<4;i++)alignButtons[i].BackColor=i==textAlign.SelectedIndex?Color.FromArgb(45,79,104):Color.FromArgb(33,37,41);};alignButtons[0].BackColor=Color.FromArgb(45,79,104);Disposed+=delegate{tips.Dispose();};}
 internal void ExpandAllForTest(){foreach(Control c in content.Controls){if(c is Panel)c.Visible=true;if(c is Button&&c.Text.StartsWith("+ "))c.Text="− "+c.Text.Substring(2);}scroll.Arrange();scroll.ScrollBy(10000);}
 void FitContent(int height){if(!IsHandleCreated||!Visible)return;int max=Math.Min(760,Screen.FromControl(this).WorkingArea.Height-60);int desired=Math.Max(180,Math.Min(max,height+28));if(Height!=desired)Height=desired;Rectangle screen=Screen.FromControl(this).WorkingArea;if(Bottom>screen.Bottom)Top=Math.Max(screen.Top,screen.Bottom-Height);}
 Button Mini(Control parent,string text,int x,int y,int width,Action action){var b=new Button{Text="",Left=x,Top=y,Width=width,Height=27,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(33,37,41),ForeColor=Color.Gainsboro,Padding=Padding.Empty,Margin=Padding.Empty};b.FlatAppearance.BorderColor=Color.FromArgb(65,72,78);b.Paint+=delegate(object sender,PaintEventArgs e){using(var f=new Font("Segoe UI",width<30?8:9))TextRenderer.DrawText(e.Graphics,text,f,new Rectangle(0,0,b.Width,b.Height),b.ForeColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);};tips.SetToolTip(b,text=="A+"?"Increase font size":text=="A−"?"Decrease font size":text=="Mark"?"Text highlight":text=="A ▾"?"Text colour":text);b.Click+=delegate{action();};parent.Controls.Add(b);return b;}
 CheckBox Toggle(Control parent,string text,int x,int y,int width,FontStyle style){var b=new CheckBox{Text=text,Left=x,Top=y,Width=width,Height=28,Appearance=Appearance.Button,TextAlign=ContentAlignment.MiddleCenter,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(33,37,41),ForeColor=Color.Gainsboro,Font=new Font(Font.FontFamily,10,style)};b.FlatAppearance.CheckedBackColor=Color.FromArgb(45,79,104);b.FlatAppearance.BorderColor=Color.FromArgb(65,72,78);parent.Controls.Add(b);return b;}
 public void ChooseHighlight(){var menu=new ContextMenuStrip{Renderer=new DarkRenderer(),BackColor=Color.Black,ForeColor=Color.Gainsboro};menu.Items.Add("No highlight",null,delegate{markColor=null;Send("stylepreview");});foreach(Color c in new[]{Color.Yellow,Color.LightGreen,Color.LightBlue,Color.LightPink}){Color color=c;menu.Items.Add(c.Name,null,delegate{markColor=color;Send("stylepreview");});}menu.Items.Add("Choose colour…",null,delegate{using(var d=new ColorDialog{Color=markColor??Color.Yellow,FullOpen=true})if(d.ShowDialog(this)==DialogResult.OK){markColor=d.Color;Send("stylepreview");}});menu.Closed+=delegate{menu.Dispose();};menu.Show(Cursor.Position);}
}
internal sealed class InlineResizeFrame : Panel {
 public readonly RichTextBox Input=new RichTextBox{Multiline=true,AcceptsTab=true,BorderStyle=BorderStyle.None,BackColor=Color.White,ForeColor=Color.Black,ScrollBars=RichTextBoxScrollBars.None,Dock=DockStyle.Fill,DetectUrls=false,HideSelection=false,EnableAutoDragDrop=false};
 public event Action ResizedByUser;bool resizing;int handle;Point press;Rectangle original;
 public InlineResizeFrame(){Padding=new Padding(2);BackColor=Color.White;Controls.Add(Input);MinimumSize=new Size(28,22);DoubleBuffered=true;}
 int Hit(Point p){int x=p.X<5?-1:p.X>Width-6?1:0,y=p.Y<5?-1:p.Y>Height-6?1:0;return (x+1)+(y+1)*3;}
 protected override void OnMouseDown(MouseEventArgs e){if(e.Button!=MouseButtons.Left)return;handle=Hit(e.Location);if(handle==4)return;resizing=true;Capture=true;press=PointToScreen(e.Location);original=Bounds;}
 protected override void OnMouseMove(MouseEventArgs e){int h=resizing?handle:Hit(e.Location);int x=h%3-1,y=h/3-1;Cursor=x==0?Cursors.SizeNS:y==0?Cursors.SizeWE:x==y?Cursors.SizeNWSE:Cursors.SizeNESW;if(!resizing)return;Point p=PointToScreen(e.Location);int dx=p.X-press.X,dy=p.Y-press.Y,l=original.Left,t=original.Top,r=original.Right,b=original.Bottom;if(x<0)l=Math.Min(r-90,l+dx);if(x>0)r=Math.Max(l+90,r+dx);if(y<0)t=Math.Min(b-45,t+dy);if(y>0)b=Math.Max(t+45,b+dy);Bounds=Rectangle.FromLTRB(l,t,r,b);if(ResizedByUser!=null)ResizedByUser();}
 protected override void OnMouseUp(MouseEventArgs e){resizing=false;Capture=false;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);using(var border=new Pen(Color.FromArgb(65,142,196),1.2f))e.Graphics.DrawRectangle(border,.6f,.6f,Width-1.2f,Height-1.2f);foreach(Point p in new[]{new Point(3,3),new Point(Width/2,3),new Point(Width-4,3),new Point(3,Height/2),new Point(Width-4,Height/2),new Point(3,Height-4),new Point(Width/2,Height-4),new Point(Width-4,Height-4)})e.Graphics.FillRectangle(Brushes.White,p.X-2,p.Y-2,4,4);}
}
}
